int far SpecialTutorialInit(char far *name)
{
    char far *p;
    int tutorial;

    p = strrchr(name, 0x5c);
    tutorial = stricmp(p ? p + 1 : name, MiscStrs[0]) == 0;
    if (tutorial) {
        GenerateTutorial();
        SetEditWinTitle("Tutorial Game");
        InitSimVars();
        SeedSRand();
        EditMessage(0L, -2, -1, 1);
    } else
        SetEditWinTitle(p ? p + 1 : name);
    return tutorial;
}
